async (page) => {
await page.goto('http://127.0.0.1:8765/');
await page.waitForTimeout(1500);
const t=await page.evaluate(()=>document.querySelector('header').innerText);
const api=await page.evaluate(async()=>await (await fetch('/api/cadre')).text());
// keyboard
await page.keyboard.press('Tab');
const f=await page.evaluate(()=>{const e=document.activeElement;const r=e.getBoundingClientRect();return {t:e.textContent.trim(),href:e.getAttribute('href'),rect:[r.x,r.y,r.width,r.height],outline:getComputedStyle(e).outlineStyle+' '+getComputedStyle(e).outlineWidth}});
await page.keyboard.press('Enter');
const g=await page.evaluate(()=>({hash:location.hash,active:document.activeElement.id||document.activeElement.tagName,tx:document.activeElement.textContent.trim()}));
const tabs=[];for(let i=0;i<9;i++){await page.keyboard.press('Tab');tabs.push(await page.evaluate(()=>document.activeElement.textContent.trim().slice(0,30)))}
await page.setViewportSize({width:390,height:844});
const sw=await page.evaluate(()=>[document.documentElement.scrollWidth,innerWidth]);
await page.screenshot({path:'m390.png'});
await page.goto('http://127.0.0.1:8765/chaine');await page.waitForTimeout(500);
const sw2=await page.evaluate(()=>[document.documentElement.scrollWidth,innerWidth,document.querySelector('header').innerText]);
await page.setViewportSize({width:1280,height:800});
return {t,api,f,g,tabs,sw,sw2};
}

